@bp.route("/workout/session/<public_id>/checkpoint", methods=["POST"])
@require_auth
@_session_flag_gated
@limiter.limit(WORKOUT_CHECKPOINT_RATELIMIT, key_func=_user_or_ip_key)
def workout_session_checkpoint(public_id):
    """Durable browser progress (Sprint 14 PR2) -- a transport adapter over the
    canonical execution authority, not a second implementation of it.

    Until PR2 this route was a heartbeat: it wrote ``last_activity_at`` and
    nothing else, so a browser workout lost every logged set on reload and a
    browser completion could silently discard progress the phone had committed.
    It now reaches exactly the authority ``#276`` built --
    :func:`workout_session.execution.record_checkpoint` -- with the same bounds,
    the same canonical ordering, the same replay identity and the same
    conditional UPDATE keyed on the caller's declared base revision.

    The request contract mirrors the native one because it is the same contract:

    * ``If-Match`` -- REQUIRED. A progress write with no declared base revision
      cannot be ordered, so there is no fallback channel and no client-supplied
      default. The value is the ``checkpoint_revision`` the caller last read.
    * ``Idempotency-Key`` -- REQUIRED. Same key + same snapshot replays without
      advancing the revision; same key + a different snapshot is a deterministic
      conflict.
    * body ``{"checkpoint": {...}}`` -- a bounded FULL snapshot, never a patch.

    Web-specific, and deliberately unchanged from the rest of this blueprint:
    cookie authentication, the app-wide two-layer CSRF gate, and ownership
    re-derived from ``current_user``. The flag gate sits outside the throttle so
    a dark surface answers 404 rather than 429.
    """
    body = request.get_json(silent=True)
    try:
        key = parse_idempotency_key(request.headers.get("Idempotency-Key"))
        revision = parse_revision(request.headers.get("If-Match"))
        payload = body.get("checkpoint") if isinstance(body, dict) else None
        result = record_checkpoint(
            current_user.id, public_id, key, revision,
            planned_exercise_identities,
            lambda allowed: parse_checkpoint(payload, allowed),
        )
    except SessionCommandError as error:
        return _session_failure(error)
    except Exception as error:  # noqa: BLE001 - never leak an internal failure
        return _session_unavailable(error, "checkpoint_failed")
    response = jsonify({
        "outcome": SessionOutcome.CHECKPOINTED.value,
        "session": result.view.to_dict(),
        "replayed": result.replayed,
    })
    response.headers["Idempotency-Replayed"] = str(result.replayed).lower()
    return response


