@bp.route("/api/training/weekly-program")
@require_auth
def get_weekly_program():
    """Read-only weekly-program recommendation for the signed-in user (Sprint 6 PR5).

    The single runtime surface of `app/services/weekly_program/` — deliberately thin:
    one service call, one pure projection, no decision of its own. AdaptivePlan stays
    the sole planning authority; nothing here reads WorkoutLog, recomputes a trend, or
    interprets a signal (`docs/WEEKLY_PROGRAM.md`).

    `weeks`/`end_day` are pinned to the service defaults rather than taken from the
    query string: the response must be deterministic for a given user and day, and a
    caller-tunable window would be a planning knob this layer has no authority to
    offer. Empty history yields the neutral recommendation, never an error.

    Failure semantics differ from the PR4 coach consumer *on purpose*. PR4 catches a
    planner failure and substitutes its neutral contract because the coach must keep
    answering; here the neutral recommendation is a legitimate user state ("not enough
    history"), so returning it on a DB/planner failure would report infrastructure
    breakage as valid data. The failure propagates as a structured JSON 500 instead,
    matching the other JSON routes in this blueprint rather than the HTML error page.
    No `db.session.rollback()` is needed: unlike PR4 the request ends here, and
    Flask-SQLAlchemy's teardown removes the session per request.
    """
    try:
        recommendation = build_weekly_program(current_user.id, weeks=4, end_day=None)
    except Exception as e:
        current_app.logger.warning(
            "[TRAINING][WEEKLY_PROGRAM] request_id=%s state=error error_class=%s",
            current_request_id(), _weekly_program_error_class(e))
        return jsonify({"error": t("route.generic_error_retry")}), 500

    # Minimum useful observability: tells "neutral because no history" apart from
    # "populated recommendation" apart from "upstream failure" (logged above) without
    # emitting history, volumes, or the payload itself.
    current_app.logger.info(
        "[TRAINING][WEEKLY_PROGRAM] request_id=%s state=%s",
        current_request_id(), _weekly_program_state(recommendation))
    return jsonify(weekly_program_payload(recommendation))


@bp.route("/water", methods=["GET"])
@require_auth
def get_water():
    today_key = app_today().isoformat()
    row = WaterLog.query.filter_by(user_id=current_user.id, date_key=today_key).first()
    return jsonify({"count": row.count if row else 0, "goal": WATER_GOAL})


@bp.route("/water", methods=["POST"])
@require_auth
@auth_write_limit
def set_water():
    data = request.get_json(silent=True) or {}
    try:
        count = int(data.get("count", 0))
    except (TypeError, ValueError):
        return jsonify({"error": t("route.invalid_value")}), 400
    count = max(0, min(count, WATER_GOAL))  # 0..8 arası kıs

    today_key = app_today().isoformat()
    row = WaterLog.query.filter_by(user_id=current_user.id, date_key=today_key).first()
    if row:
        row.count = count
        db.session.commit()
    else:
        row = WaterLog(user_id=current_user.id, date_key=today_key, count=count)
        db.session.add(row)
        try:
            db.session.commit()
        except IntegrityError:
            # Yarış: günün ilk iki eşzamanlı isteği de "satır yok" gördü;
            # uq_user_water_day ikinci INSERT'i reddetti. Rollback edip mevcut
            # satırı çekerek güncelle (500 yerine tutarlı sonuç).
            db.session.rollback()
            row = WaterLog.query.filter_by(user_id=current_user.id, date_key=today_key).first()
            if row is None:
                raise
            row.count = count
            db.session.commit()

    # Su takibi güncellenince "Su Hedefi" görevini ver (günde bir kez claim edilir;
    # complete_quest_for_user zaten claimliyse None döner). Önceden seed'leniyordu
    # ama hiç claim edilmiyordu (ölü görev — 1.1).
    resp = {"count": row.count, "goal": WATER_GOAL}
    if count > 0 and _claim_water_funnel_for_today(current_user.id, today_key):
        quest_result = complete_quest_for_user(current_user.id, "water_logged")
        if quest_result:
            resp["quest_awarded"] = quest_result
    return jsonify(resp)


def _claim_water_funnel_for_today(user_id, today_key):
    """Günün su hunisini (water_logged) TEK sefer talep et. True = bu istek aldı.

    Huni GÜN-anlamlıdır: weekly_water challenge'ı "5 GÜN" sayar ve
    challenges.record_event'in per-day dedup'ı YOKTUR — dedup çağıranın
    sorumluluğu (active_day deseni). Eski kapı `count > 0 and prev_count == 0`
    kullanıcının kendi SIFIRLAYABİLDİĞİ sayıya bakıyordu: 5 → 0 → 5 toggle'ı
    geçişi yeniden silahlandırıp huniyi aynı gün defalarca ateşliyordu, yani
    "5 gün" challenge'ı tek öğleden sonrada tamamlanabiliyordu
    (triage 2026-08-07 #1 / 2026-08-14 #1).

    Kalıcı gün-başı işaret (WaterLog.quest_fired) toggle'a dayanıklıdır; koşullu
    UPDATE ... WHERE quest_fired = false, uq_user_water_day sayesinde satırın
    kendisi gün-başına tek olduğu için eşzamanlı iki isteğin ikisinin birden
    ateşlemesini de engeller (DB-düzeyi tek iddia; ayrı kilit gerekmez).
    """
    claimed = (db.session.query(WaterLog)
               .filter(WaterLog.user_id == user_id,
                       WaterLog.date_key == today_key,
                       WaterLog.quest_fired.is_(False))
               .update({WaterLog.quest_fired: True}, synchronize_session=False))
    db.session.commit()
    return bool(claimed)


WATER_GOAL = 8  # bardak
